BASE = "SELECT id, name, email FROM users"
TAIL = "ORDER BY created_at DESC LIMIT ?"
EVIL = "x'; DROP TABLE users; --"
def query(filters, limit=10):
    """build_user_query, with the whitespace of the SQL squeezed and the params as a list."""
    sql, params = build_user_query(filters, limit)
    return " ".join(sql.split()), list(params)
def where_of(filters):
    """Just the WHERE part of the SQL ("" when there is none) and the filter values (the LIMIT value left out)."""
    sql, params = query(filters)
    return sql.removeprefix(BASE).split(" ORDER BY ")[0].strip(), params[:-1]
def keeps_the_value_out_of_the_sql(filters):
    sql, params = build_user_query(filters, 10)
    for text in (EVIL, "DROP", "--", "'"):
        if text in sql:
            raise AssertionError(f"user text reached the SQL ({text!r} is in it): {sql!r}")
    if EVIL not in params:
        raise AssertionError(f"the value must travel in params, but params is {list(params)!r}")
    if sql.count("?") != len(params):
        raise AssertionError(f"{sql.count('?')} placeholders but {len(params)} params")
    return True
def rejects(filters, limit=10):
    """True when build_user_query raises ValueError for these arguments."""
    try:
        result = build_user_query(filters, limit)
    except ValueError:
        return True
    raise AssertionError(f"expected ValueError for filters={filters!r} and limit={limit!r}, but got {result!r}")
